class Solution:
    def countValidSubarrays(self, nums: list[int], x: int) -> int:
        def isValid(sum: int, target: int) -> bool:
            sumStr = str(sum)
            targetStr = str(target)
            return sumStr[0] == targetStr and sumStr[-1] == targetStr

        ans = 0
        n = len(nums)
        for i in range(n):
            sum = 0
            for j in range(i, n):
                sum += nums[j]
                if isValid(sum, x):
                    ans += 1
        return ans
